t.script:
document.addEventListener('DOMContentLoaded', function() {
    var searchInput = document.getElementById('repairSearch');
    var filterBtns = document.querySelectorAll('.filter-chip');
    var tableRows = document.querySelectorAll('#repairTable .repair-row');
    var cardRows = document.querySelectorAll('#repairCards .repair-row');
    var noResults = document.getElementById('noResults');
    var resultCount = document.getElementById('resultCount');
    var activeFilter = 'all';

    function filterRow(row, query) {
        var matchState = (activeFilter === 'all') || (row.getAttribute('data-state') === activeFilter);
        var searchText = row.getAttribute('data-search-text') || '';
        var matchSearch = !query || searchText.indexOf(query) !== -1;
        var show = matchState && matchSearch;
        row.classList.toggle('d-none', !show);
        return show;
    }

    function applyFilters() {
        var query = (searchInput.value || '').toLowerCase().trim();
        var visible = 0;
        tableRows.forEach(function(row) { if (filterRow(row, query)) visible++; });
        cardRows.forEach(function(row) { filterRow(row, query); });
        if (noResults) noResults.classList.toggle('d-none', visible > 0);
        if (resultCount) resultCount.textContent = visible + ' equipo' + (visible !== 1 ? 's' : '');
    }

    if (searchInput) searchInput.addEventListener('input', applyFilters);

    filterBtns.forEach(function(btn) {
        btn.addEventListener('click', function() {
            filterBtns.forEach(function(b) { b.classList.remove('active'); });
            btn.classList.add('active');
            activeFilter = btn.getAttribute('data-filter');
            applyFilters();
        });
    });
});
